import json
import sys

def generate_token(username, secret):
    return f"{username}{secret}"

def verify_token(username, token, secret):
    expected_token = generate_token(username, secret)
    return token == expected_token

def main():
    if len(sys.argv) < 3:
        print("Usage: python auth_check.py <mode> <username> [token]")
        sys.exit(1)

    mode = sys.argv[1]
    username = sys.argv[2]

    try:
        with open("config.json", "r") as f:
            config = json.load(f)
    except FileNotFoundError:
        print("Error: config.json not found")
        sys.exit(1)
    except json.JSONDecodeError:
        print("Error: config.json is not valid JSON")
        sys.exit(1)

    if username not in config["users"]:
        print("Error: username not found in config")
        sys.exit(1)

    secret = config["secret"]

    if mode == "generate":
        token = generate_token(username, secret)
        print(token)
    elif mode == "verify":
        if len(sys.argv) != 4:
            print("Usage: python auth_check.py verify <username> <token>")
            sys.exit(1)
        token = sys.argv[3]
        if verify_token(username, token, secret):
            print("ACCEPT")
        else:
            print("REJECT")
    else:
        print("Error: invalid mode")
        sys.exit(1)

    sys.exit(0)

if __name__ == "__main__":
    main()

